const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='archive_v010', PREF='archive_preferences_v010';
const uid=()=>crypto.randomUUID?.()||('id-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const initial=()=>({version:2,binders:[],groups:[],cards:[],tags:[]});
// v0.1.8: optional, type-specific metadata. Legacy items without details remain valid.
const validItemDetails=value=>value===undefined||(value!==null&&typeof value==='object'&&!Array.isArray(value));
const itemDetails=value=>validItemDetails(value)&&value!==undefined?structuredClone(value):{};
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&Array.isArray(x.binders)&&Array.isArray(x.cards)&&Array.isArray(x.tags)?x:initial()}catch{return initial()}}
let db=load();
// Non-destructive upgrade: each legacy collection receives a default group.
function migrateGroups(){if(!Array.isArray(db.groups))db.groups=[];let changed=false;for(const b of db.binders){let groups=db.groups.filter(g=>g.binderId===b.id);if(!groups.length&&db.cards.some(c=>c.binderId===b.id)){const group={id:uid(),binderId:b.id,name:'Unsorted'};db.groups.push(group);groups=[group];changed=true}for(const c of db.cards.filter(c=>c.binderId===b.id)){if(!groups.some(g=>g.id===c.groupId)){c.groupId=groups[0].id;changed=true}}}if(changed){db.version=2;localStorage.setItem(KEY,JSON.stringify(db))}}
migrateGroups();
let view={binder:null,group:null,card:null,search:false},words=[],filters=[],draft='',sort='default',editMode=false,selected=new Set(),prefs=(()=>{try{return JSON.parse(localStorage.getItem(PREF))||{}}catch{return {}}})();
// Per-collection and per-group catalogue preferences are stored separately from records.
// Existing global choices remain the fallback for newly created collections/groups.
const collectionViewModes=new Set(['default','compact']);
const itemViewModes=new Set(['compact','detailed','grid','binder','detailed-grid']);
function normalizedItemView(mode){return mode==='detailed-grid'?'grid':mode}
function collectionCatalogueMode(id){const mode=prefs.collectionGroupViews?.[id]||prefs.groupCatalogueView||'default';return collectionViewModes.has(mode)?mode:'default'}
function itemCatalogueMode(id){const mode=normalizedItemView(prefs.groupItemViews?.[id]||prefs.catalogueView||'detailed');return itemViewModes.has(mode)?mode:'detailed'}
function pruneCataloguePrefs(next){
 const collections=new Set(next.binders.map(b=>b.id)),groups=new Set(next.groups.map(g=>g.id));
 for(const id of Object.keys(prefs.collectionGroupViews||{}))if(!collections.has(id))delete prefs.collectionGroupViews[id];
 for(const id of Object.keys(prefs.groupItemViews||{}))if(!groups.has(id))delete prefs.groupItemViews[id];
}
function savePrefs(){localStorage.setItem(PREF,JSON.stringify(prefs))}
function applyTheme(){document.documentElement.dataset.theme=prefs.theme==='light'?'light':'dark'}
applyTheme();
function save(next){const json=JSON.stringify(next);localStorage.setItem(KEY,json);db=next;pruneCataloguePrefs(next);savePrefs();render()}
function update(fn){const next=structuredClone(db);fn(next);save(next)}
function formatStatus(el,message,error=false){if(!el)return;el.replaceChildren();el.className=error?'error':'';const action=/\b(created|renamed|added|updated|deleted|moved|tagged|untagged|removed|enabled|disabled|restored|exported|imported|merged|favorited|unfavorited|failed|saved)\b/gi;let pos=0,match;while((match=action.exec(message))){if(match.index>pos)el.append(document.createTextNode(message.slice(pos,match.index)));const strong=document.createElement('strong');strong.textContent=match[0];el.append(strong);pos=action.lastIndex}if(pos<message.length)el.append(document.createTextNode(message.slice(pos)))}
function status(message,error=false){const settingsEl=$('settingsStatus');if(settingsEl){formatStatus(settingsEl,message,error);formatStatus($('status'),'',false)}else formatStatus($('status'),message,error)}
function clearStatus(){status('')}
function notify(msg){status(msg,/\b(fail|error|invalid|could not|cannot|unable|required|does not match)\b/i.test(msg))}
function modal(title,body,actions=[]){$('modalRoot').innerHTML=`<div class="modalShade"><div class="modal"><h2>${esc(title)}</h2>${body}<div class="actions" id="modalActions"></div></div></div>`;const root=$('modalRoot'),bar=$('modalActions');if(/^(?:Add item|Edit item|New shelf|Edit shelf|New (?:binder|shelf|display|group)|Edit (?:binder|shelf|display|group)|Add duplicate|Edit copy)$/i.test(title))root.querySelector('.modal')?.classList.add('archiveFormModal');for(const a of actions){const b=document.createElement('button');b.textContent=a.text||'✓';b.title=a.title||a.text;b.className=a.class||'';b.onclick=()=>a.fn?.();bar.append(b)}root.querySelector('.modalShade').addEventListener('click',e=>{if(e.target.classList.contains('modalShade')){if(root.querySelector('.modal[data-editor]'))safeCloseEditor();else closeModal()}});return root}
function closeModal(){ $('modalRoot').innerHTML='' }
function confirmText(title,message,token,onYes,always=false){if(!always&&prefs.confirmations===false){closeModal();onYes();return}modal(title,`<p>${message}</p><label class="field">Type <b>${token}</b> to confirm<input id="confirmWord" autocomplete="off"></label>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Confirm',fn:()=>{if($('confirmWord').value!==token)return notify('Confirmation does not match');onYes();closeModal()}}])}
function attachBookSuggestions(){const input=document.querySelector('[data-book-field="author"]');if(!input||input.closest('[hidden]'))return;const values=[...new Set(db.cards.filter(c=>collectibleTypeForItem(c)==='books').map(c=>String(c.details?.author||'').trim()).filter(Boolean))];const list=document.createElement('datalist');list.id='bookAuthorSuggestions';for(const value of values.sort((a,b)=>a.localeCompare(b))){const o=document.createElement('option');o.value=value;list.append(o)}input.after(list);input.setAttribute('list',list.id)}
function confirmEdit(onYes,subject='this item'){if(prefs.confirmations===false){onYes();return}modal(`Edit ${subject}?`,`<p>Do you want to make changes?</p>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Edit',fn:()=>{closeModal();onYes()}}])}
const dateInput=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.slice(8)+'-'+value.slice(5,7)+'-'+value.slice(0,4):(value||'');
const parseDate=value=>{const m=/^(\d{2})-(\d{2})-(\d{4})$/.exec((value||'').trim());if(!m)return null;const iso=`${m[3]}-${m[2]}-${m[1]}`;const d=new Date(iso+'T12:00:00');return d.getFullYear()===+m[3]&&d.getMonth()+1===+m[2]&&d.getDate()===+m[1]?iso:null};
const displayDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.slice(8,10)+'-'+value.slice(5,7)+'-'+value.slice(0,4):(value||'—');
const SHELF_TYPES=[['cards','🎴','Cards'],['diecasts','🚗','Diecasts'],['plants','🌱','Plants'],['books','📚','Books'],['figures','🧸','Figures'],['other','📦','Other']];
const shelfType=b=>SHELF_TYPES.find(t=>t[0]===b?.type)||SHELF_TYPES[SHELF_TYPES.length-1];
const shelfTypeName=b=>shelfType(b)[2];
const binderName=id=>db.binders.find(b=>b.id===id)?.name||'Unknown shelf';
const groupTerms={cards:['Binder','Binders'],diecasts:['Shelf','Shelves'],books:['Shelf','Shelves'],plants:['Group','Groups'],figures:['Display','Displays'],other:['Group','Groups']};
function terms(binderId){const b=db.binders.find(x=>x.id===binderId);return groupTerms[b?.type]||groupTerms.other}
function groupsFor(binderId){return db.groups.filter(g=>g.binderId===binderId)}
function groupName(id){return db.groups.find(g=>g.id===id)?.name||'Unsorted'}
// CA-style inline validation shared by Collection and Group editors.
function singleEmoji(value){
 const text=String(value||'').trim();if(!text)return false;
 const segments=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(text)].map(x=>x.segment):[text];
 if(segments.length!==1)return false;
 // A single grapheme alone is insufficient: reject letters, numbers and punctuation.
 return /\p{Extended_Pictographic}/u.test(text)||/^(?:\p{Regional_Indicator}{2})$/u.test(text)||/^[0-9#*]\uFE0F?\u20E3$/u.test(text);
}
function clearInlineError(input){if(!input)return;input.classList.remove('fieldInvalid');input.removeAttribute('aria-invalid');const hint=input.parentElement?.querySelector('.fieldError');if(hint)hint.remove()}
function inlineError(input,message){if(!input)return false;clearInlineError(input);input.classList.add('fieldInvalid');input.setAttribute('aria-invalid','true');const hint=document.createElement('small');hint.className='fieldError';hint.setAttribute('role','alert');hint.textContent=message;input.insertAdjacentElement('afterend',hint);return false}
function validateEditorFields(fields){let first=null;for(const [input,valid,message] of fields){if(!valid){inlineError(input,message);first??=input}else clearInlineError(input)}if(first){first.focus();return false}return true}
function attachInlineValidation(ids){for(const id of ids){const input=$(id);if(input)input.addEventListener('input',()=>clearInlineError(input))}}
const DESCRIPTION_LIMIT=150;
function descriptionEditor(id,value,label){return `<label class="field">${label}<textarea id="${id}" maxlength="${DESCRIPTION_LIMIT}">${esc(value||'')}</textarea><small class="descriptionCounter" id="${id}Counter"></small></label>`}
function wireDescriptionCounter(id){const input=$(id),counter=$(id+'Counter');if(!input||!counter)return;const refresh=()=>{counter.textContent=`${input.value.length} / ${DESCRIPTION_LIMIT} characters`;clearInlineError(input)};input.addEventListener('input',refresh);refresh()}
function descriptionIsValid(id,previous){const input=$(id);return input.value.trim().length<=DESCRIPTION_LIMIT||input.value===String(previous||'')}
function groupEditor(id){
 const existing=db.groups.find(g=>g.id===id);const parent=existing?.binderId||view.binder;if(!parent)return;
 const word=terms(parent)[0];
 modal(existing?'Edit '+word:'New '+word,`<label class="field">${word} name<input id="groupName" maxlength="40" value="${esc(existing?.name||'')}"></label><label class="field">${word} emoji (optional)<input id="groupEmoji" maxlength="12" value="${esc(existing?.emoji||'')}" placeholder="Defaults to collection emoji"></label>${descriptionEditor('groupDescription',existing?.description,word+' description (optional)')}`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Save',fn:()=>{
 const name=$('groupName').value.trim();const description=$('groupDescription').value.trim();const emoji=$('groupEmoji').value.trim();if(!validateEditorFields([[$('groupName'),!!name,'Name is required.'],[$('groupEmoji'),!emoji||singleEmoji(emoji),'Enter one emoji only (not text or multiple emojis).'],[$('groupDescription'),descriptionIsValid('groupDescription',existing?.description),'Description must be 150 characters or fewer.']]))return;
 update(d=>{if(existing){const g=d.groups.find(g=>g.id===id);g.name=name;g.description=description;g.emoji=emoji}else d.groups.push({id:uid(),binderId:parent,name,description,emoji})});closeModal();notify(`${word} ${name} ${existing?'updated':'created'}`)
 }}]);
 attachInlineValidation(['groupName','groupEmoji']);wireDescriptionCounter('groupDescription');
}

function moveGroup(id,direction){
 const siblings=groupsFor(view.binder),at=siblings.findIndex(g=>g.id===id),target=at+direction;
 if(at<0||target<0||target>=siblings.length)return;
 const otherId=siblings[target].id;
 update(d=>{const a=d.groups.findIndex(g=>g.id===id),b=d.groups.findIndex(g=>g.id===otherId);if(a>=0&&b>=0)[d.groups[a],d.groups[b]]=[d.groups[b],d.groups[a]]});
 groupManager();
}
function groupManager(){
 const word=terms(view.binder)[0],groups=groupsFor(view.binder);
 modal('Manage '+terms(view.binder)[1],`<div id="groupRows">${groups.map((g,i)=>`<div class="listRow groupManageRow"><span>${esc(g.name)} (${db.cards.filter(c=>c.groupId===g.id).length})</span><button data-up-group="${esc(g.id)}" title="Move up" ${i===0?'disabled':''}>↑</button><button data-down-group="${esc(g.id)}" title="Move down" ${i===groups.length-1?'disabled':''}>↓</button><button data-edit-group="${esc(g.id)}" title="Edit">✎</button><button data-del-group="${esc(g.id)}" title="Delete">🗑</button></div>`).join('')}</div>`,[{text:'＋',title:'Add '+word,fn:()=>groupEditor()},{text:'✓',title:'Done',fn:closeModal}]);
 document.querySelectorAll('[data-up-group]').forEach(x=>x.onclick=()=>moveGroup(x.dataset.upGroup,-1));
 document.querySelectorAll('[data-down-group]').forEach(x=>x.onclick=()=>moveGroup(x.dataset.downGroup,1));
 document.querySelectorAll('[data-edit-group]').forEach(x=>x.onclick=()=>groupEditor(x.dataset.editGroup));
 document.querySelectorAll('[data-del-group]').forEach(x=>x.onclick=()=>{
 const id=x.dataset.delGroup,count=db.cards.filter(c=>c.groupId===id).length;
 if(count)return notify('Move or delete the '+count+' items before deleting this '+word.toLowerCase());
 if(groupsFor(view.binder).length===1)return notify('Keep at least one '+word.toLowerCase());
 confirmText('Delete '+word+'?',`Delete ${esc(groupName(id))}?`,'DELETE',()=>{const name=groupName(id);update(d=>{d.groups=d.groups.filter(g=>g.id!==id)});groupManager();notify(`${word} ${name} deleted`)})
 });
}
function tileFavorites(n){return n>0?' · '+n+' ♡':''}
function placeCatalogueDescription(){
 const meta=document.querySelector('.catalogueMeta');if(!meta)return;
 meta.querySelectorAll(':scope > .catalogueDescriptionRow').forEach(el=>el.remove());
 const description=$('context')?.querySelector('.collectionPageDescription,.groupPageDescription');
 if(!description)return;
 const row=document.createElement('div');row.className='catalogueDescriptionRow';
 row.appendChild(description);meta.appendChild(row);
}
function renderGroups(){const b=db.binders.find(x=>x.id===view.binder);const word=terms(view.binder);const compact=collectionCatalogueMode(view.binder)==='compact';$('content').classList.remove('compactView','compactListing');$('content').classList.add('groupPageTiles');$('content').classList.toggle('groupCompactTiles',compact);$('context').innerHTML=`<span class="binderStats"><span class="binderCounter">${esc(shelfTypeName(b).toUpperCase())} · ${countLabel(groupsFor(view.binder).length,word[0].toUpperCase(),word[1].toUpperCase())} · ${countLabel(totalCards(db.cards.filter(c=>c.binderId===view.binder)),'ITEM','ITEMS')}</span>${b.description?.trim()?`<span class="collectionPageDescription">${esc(b.description)}</span>`:''}</span><button class="icon" id="manageGroups" title="Manage ${word[1]}">✎</button>`;$('manageGroups').onclick=()=>groupManager();placeCatalogueDescription();$('content').innerHTML=groupsFor(view.binder).length?`<div class="grid">${groupsFor(view.binder).map(g=>{const items=db.cards.filter(c=>c.groupId===g.id);const total=totalCards(items);const favorites=items.filter(c=>c.favorite).length;return `<button class="binder groupTile ${compact?'groupTileCompact':''}" data-group="${esc(g.id)}"><span class="groupTileEmoji" aria-hidden="true">${esc(g.emoji||b?.emoji||shelfType(b)[1])}</span><span class="groupTileText"><strong class="groupTileName">${esc(g.name)}</strong>${compact&&g.description?.trim()?`<span class="groupTileDescription">${esc(g.description)}</span>`:''}</span><span class="groupTileCounts"><small>${countLabel(total,'ITEM','ITEMS')}</small>${favorites>0?`<small>${favorites} ♡</small>`:''}</span></button>`}).join('')}</div>`:'<div class="empty">No '+word[1].toLowerCase()+' yet.</div>';document.querySelectorAll('[data-group]').forEach(x=>x.onclick=()=>{view.group=x.dataset.group;editMode=false;selected.clear();render()})}
function updateHeader(){const b=db.binders.find(x=>x.id===view.binder);const g=db.groups.find(x=>x.id===view.group);const el=$('archiveHeading');if(el)el.textContent='ARCHIVE'+(b?' / '+(b.emoji||shelfType(b)[1])+(g?'':' '+b.name):'')+(g?' / '+(g.emoji||shelfType(b)[1])+' '+g.name:'')}

