function typeEditorFields(type,details={}){if(type==='other')return otherCustomEditor(details);const fields=TYPE_DETAIL_FIELDS[type]||[];return fields.map(([key,label])=>`<label class="field">${label}<input data-type-field="${key}" maxlength="${/^(?:brand|manufacturer|make)$/i.test(key)?60:/^(?:model|series|title)$/i.test(key)?80:/^(?:color|colour|variant)$/i.test(key)?60:/^(?:condition|status)$/i.test(key)?40:120}" value="${esc(details[key]||'')}"></label>`).join('')}
function readTypeDetails(existing){const d=itemDetails(existing);if(editorType()==='other')d.customFields=readOtherCustomFields();document.querySelectorAll('[data-type-field]').forEach(el=>{const v=el.value.trim();if(v)d[el.dataset.typeField]=v;else delete d[el.dataset.typeField]});return d}
