function otherCustomRow(name='',value=''){return `<div class="otherCustomRow"><label class="field">Field name<input class="otherFieldName" maxlength="40" placeholder="e.g. Color" value="${esc(name)}"></label><label class="field otherCustomValueLabel">Value<input class="otherFieldValue" maxlength="240" value="${esc(value)}"></label><button type="button" class="icon removeOtherField" title="Remove field">✕</button></div>`}
function readOtherCustomFields(){return [...document.querySelectorAll('.otherCustomRow')].map(row=>({name:row.querySelector('.otherFieldName').value.trim(),value:row.querySelector('.otherFieldValue').value.trim()})).filter(x=>x.name||x.value)}
function wireOtherCustomFields(){const rows=$('otherCustomRows'),add=$('addOtherCustomField');if(!rows||!add)return;const all=()=>db.cards.filter(c=>shelfType(db.binders.find(b=>b.id===c.binderId))[0]==='other').flatMap(c=>Array.isArray(c.details?.customFields)?c.details.customFields:[]);const suggest=()=>{document.querySelectorAll('.otherCustomRow').forEach(row=>{const name=row.querySelector('.otherFieldName'),value=row.querySelector('.otherFieldValue');let names=$('otherFieldNameSuggestions');if(!names){names=document.createElement('datalist');names.id='otherFieldNameSuggestions';document.body.append(names)}names.replaceChildren(...[...new Map(all().map(x=>[x.name.toLowerCase(),x.name])).values()].filter(Boolean).map(v=>{const o=document.createElement('option');o.value=v;return o}));name.setAttribute('list',names.id);const id='otherValueSuggestions_'+[...rows.children].indexOf(row);let dl=document.getElementById(id);if(!dl){dl=document.createElement('datalist');dl.id=id;document.body.append(dl)}const values=all().filter(x=>x.name.toLowerCase()===name.value.trim().toLowerCase()).map(x=>x.value).filter(Boolean);dl.replaceChildren(...[...new Map(values.map(v=>[v.toLowerCase(),v])).values()].map(v=>{const o=document.createElement('option');o.value=v;return o}));value.setAttribute('list',id)});};rows.addEventListener('input',suggest);rows.addEventListener('click',e=>{if(e.target.closest('.removeOtherField')){e.target.closest('.otherCustomRow').remove();suggest()}});add.onclick=()=>{rows.insertAdjacentHTML('beforeend',otherCustomRow());suggest()};suggest()}
