// A separate quantity dialog sits above the item editor without replacing its form.
function duplicateQuantityDialog(cardId){
  if($('duplicateQuantityShade'))return;
  const parent=db.cards.find(c=>c.id===cardId);if(!parent)return;
  const overlay=document.createElement('div');overlay.id='duplicateQuantityShade';overlay.className='duplicateQuantityShade';
  overlay.innerHTML=`<div class="duplicateQuantityModal" role="dialog" aria-modal="true" aria-labelledby="duplicateQuantityTitle"><h2 id="duplicateQuantityTitle">ADD AS DUPLICATE</h2><p>How many copies?</p><div class="duplicateQuantityControls"><button id="duplicateMinus" type="button" aria-label="Decrease quantity">−</button><input id="duplicateQuantity" type="number" inputmode="numeric" min="1" max="99" step="1" value="1" aria-label="Number of copies"><button id="duplicatePlus" type="button" aria-label="Increase quantity">＋</button></div><div class="actions"><button id="duplicateCancel" type="button">✕</button><button id="duplicateConfirm" type="button" class="primary">ADD COPIES</button></div></div>`;
  $('modalRoot').append(overlay);
  const field=$('duplicateQuantity'),minus=$('duplicateMinus'),plus=$('duplicatePlus'),confirm=$('duplicateConfirm');
  const read=()=>{const n=Number(field.value);return Number.isInteger(n)&&n>=1&&n<=99?n:null};
  const adjust=delta=>{field.value=String(Math.max(1,Math.min(99,(read()||1)+delta)));refresh()};
  const refresh=()=>{const n=read();minus.disabled=n===1;plus.disabled=n===99;confirm.disabled=n===null;confirm.textContent=n===1?'ADD 1 COPY':`ADD ${n||''} COPIES`};
  minus.onclick=()=>adjust(-1);plus.onclick=()=>adjust(1);field.oninput=refresh;
  const close=()=>overlay.remove();$('duplicateCancel').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close()};
  confirm.onclick=async()=>{const count=read();if(!count||confirm.disabled)return;
    if($('modalRoot').querySelector('.modal[data-dirty="true"]')&&!window.confirm('Unsaved edits will not be copied. Add duplicates using the last saved item details?'))return;
    confirm.disabled=true;minus.disabled=true;plus.disabled=true;field.disabled=true;
    const newImageIds=[];
    try{
      const current=db.cards.find(c=>c.id===cardId);if(!current)throw Error('Card no longer exists');
      const sourceImage=current.imageId?await loadImage(current.imageId):null;
      if(current.imageId&&(!(sourceImage instanceof Blob)||!sourceImage.size))throw Error('Original image could not be read');
      const copies=[];
      for(let i=0;i<count;i++){
        let imageId=null;
        if(sourceImage){imageId=uid();await putImage(imageId,sourceImage);newImageIds.push(imageId)}
        copies.push({id:uid(),condition:current.condition||'',language:current.language||'',pack:current.pack||'',dateBought:current.dateBought||'',description:current.description||'',details:itemDetails(current.details),imageId});
      }
      update(d=>{const card=d.cards.find(c=>c.id===cardId);if(!card)throw Error('Card no longer exists');card.copies=card.copies||[];card.copies.push(...copies)});
      // The editor remains open; its stale copy array must not overwrite newly added copies.
      const editor=$('modalRoot').querySelector('.modal[data-editor]');if(editor)editor.dataset.duplicateAdded='true';
      close();notify(`Added ${count} ${count===1?'copy':'copies'}`);
    }catch(err){for(const id of newImageIds)await deleteImage(id).catch(()=>{});notify('Could not add duplicates: '+err.message);confirm.disabled=false;field.disabled=false;refresh()}
  };
  refresh();field.focus();field.select();
}
