async function loadImages(root){for(const img of root.querySelectorAll('img[data-img]')){const id=img.dataset.img;try{const blob=await loadImage(id);if(!img.isConnected)continue;if(!(blob instanceof Blob)||!blob.size){img.alt='Image unavailable';img.classList.add('imageMissing');continue}const url=URL.createObjectURL(blob);img.onload=()=>{URL.revokeObjectURL(url);img.onload=null};img.onerror=()=>{URL.revokeObjectURL(url);img.alt='Image could not be displayed';img.classList.add('imageMissing')};img.src=url}catch(e){console.error('Image retrieval failed',id,e);if(img.isConnected){img.alt='Image unavailable';img.classList.add('imageMissing')}}}}
function cropImage(file,onDone){const img=new Image(),source=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(source);const shade=document.createElement('div');shade.className='modalShade cropShade';shade.innerHTML=`<div class="modal"><h2>Crop image</h2><div class="cropSurface"><canvas id="cropCanvas"></canvas><div class="cropSelection" id="cropSelection"><i data-corner="tl"></i><i data-corner="tr"></i><i data-corner="bl"></i><i data-corner="br"></i></div></div><div class="row"><button id="cropRotate" title="Rotate image">⟳</button><button id="cropReset" title="Reset crop">↺</button></div><p class="help">Drag a corner to resize. Drag inside the rectangle to move the crop.</p><div class="actions"><button id="cropCancel" title="Cancel">✕</button><button id="cropSave" title="Save crop">✓</button></div></div>`;document.body.append(shade);const canvas=shade.querySelector('canvas'),ctx=canvas.getContext('2d'),sel=shade.querySelector('#cropSelection');let rotation=0,box={x:.1,y:.1,w:.8,h:.8};const draw=()=>{const rotated=rotation%180!==0;const iw=rotated?img.height:img.width,ih=rotated?img.width:img.height;const maxW=Math.min(440,window.innerWidth-68),maxH=Math.min(440,window.innerHeight*.48),scale=Math.min(maxW/iw,maxH/ih,1);canvas.width=Math.max(1,Math.round(iw*scale));canvas.height=Math.max(1,Math.round(ih*scale));ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(img,-img.width*scale/2,-img.height*scale/2,img.width*scale,img.height*scale);ctx.restore();position()};function position(){sel.style.left=(box.x*100)+'%';sel.style.top=(box.y*100)+'%';sel.style.width=(box.w*100)+'%';sel.style.height=(box.h*100)+'%'}draw();let drag=null;sel.addEventListener('pointerdown',e=>{e.preventDefault();const corner=e.target.dataset.corner||'move';drag={corner,startX:e.clientX,startY:e.clientY,initial:{...box}};sel.setPointerCapture(e.pointerId)});sel.addEventListener('pointermove',e=>{if(!drag)return;const rect=canvas.getBoundingClientRect(),dx=(e.clientX-drag.startX)/rect.width,dy=(e.clientY-drag.startY)/rect.height,b={...drag.initial},min=.07;switch(drag.corner){case'tl':b.x+=dx;b.y+=dy;b.w-=dx;b.h-=dy;break;case'tr':b.y+=dy;b.w+=dx;b.h-=dy;break;case'bl':b.x+=dx;b.w-=dx;b.h+=dy;break;case'br':b.w+=dx;b.h+=dy;break;default:b.x+=dx;b.y+=dy}b.w=Math.max(min,Math.min(b.w,1));b.h=Math.max(min,Math.min(b.h,1));b.x=Math.max(0,Math.min(b.x,1-b.w));b.y=Math.max(0,Math.min(b.y,1-b.h));box=b;position()});sel.addEventListener('pointerup',()=>drag=null);sel.addEventListener('pointercancel',()=>drag=null);shade.querySelector('#cropRotate').onclick=()=>{rotation=(rotation+90)%360;box={x:.1,y:.1,w:.8,h:.8};draw()};shade.querySelector('#cropReset').onclick=()=>{box={x:.1,y:.1,w:.8,h:.8};position()};shade.querySelector('#cropCancel').onclick=()=>shade.remove();shade.querySelector('#cropSave').onclick=()=>{const out=document.createElement('canvas'),cw=Math.round(canvas.width*box.w),ch=Math.round(canvas.height*box.h),factor=Math.min(1,1600/Math.max(cw,ch));out.width=Math.max(1,Math.round(cw*factor));out.height=Math.max(1,Math.round(ch*factor));out.getContext('2d').drawImage(canvas,box.x*canvas.width,box.y*canvas.height,cw,ch,0,0,out.width,out.height);out.toBlob(blob=>{if(blob&&blob.size){onDone(blob);shade.remove()}else notify('Image conversion failed')},'image/jpeg',.83)}};img.onerror=()=>{URL.revokeObjectURL(source);notify('Cannot open image')};img.src=source}
function imageViewer(c){const root=document.createElement('div');root.className='viewer';root.innerHTML=`<div class="top"><button class="icon" id="viewBack" title="Back">←</button><div class="row"><button class="icon" id="viewEdit" title="Edit item">✎</button><button class="icon" id="viewClose" title="Close">✕</button></div></div><div class="stage"><img alt="Item image"></div><div class="hint">Pinch, scroll, or double-tap to zoom</div>`;document.body.append(root);const pic=root.querySelector('img');let scale=1,x=0,y=0;const pointers=new Map();let lastDistance=0,lastX=0,lastY=0;function apply(){pic.style.transform=`translate(${x}px,${y}px) scale(${scale})`}loadImage(c.imageId).then(blob=>{if(blob&&root.isConnected){const url=URL.createObjectURL(blob);pic.src=url;pic.onload=()=>URL.revokeObjectURL(url)}});const close=()=>root.remove();root.querySelector('#viewBack').onclick=close;root.querySelector('#viewClose').onclick=close;root.querySelector('#viewEdit').onclick=()=>confirmEdit(()=>{close();cardEditor(c.id)});const stage=root.querySelector('.stage');stage.onwheel=e=>{e.preventDefault();scale=Math.max(1,Math.min(8,scale*(e.deltaY<0?1.15:.87)));if(scale===1)x=y=0;apply()};stage.ondblclick=()=>{scale=scale>1?1:2.5;x=y=0;apply()};stage.onpointerdown=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});stage.setPointerCapture(e.pointerId);lastX=e.clientX;lastY=e.clientY;lastDistance=0};stage.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(lastDistance)scale=Math.max(1,Math.min(8,scale*d/lastDistance));lastDistance=d}else if(scale>1){x+=e.clientX-lastX;y+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY}apply()};stage.onpointerup=stage.onpointercancel=e=>{pointers.delete(e.pointerId);lastDistance=0};root.onkeydown=e=>{if(e.key==='Escape')close()}}
const blobToData=blob=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)});
const dataToBlob=data=>{const [meta,body]=data.split(',');if(!meta?.startsWith('data:image/')||!body)throw Error('Invalid image');const bytes=atob(body),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:meta.slice(5).split(';')[0]})};
async function exportBackup(){try{const images={};for(const id of new Set(allImageIds(db.cards))){const blob=await loadImage(id);if(!blob)throw Error('Missing stored image '+id);images[id]=await blobToData(blob)}const data={format:'archive',version:1,exportedAt:new Date().toISOString(),binders:db.binders,groups:db.groups,cards:db.cards,tags:db.tags,images,viewPreferences:{collectionGroupViews:Object.fromEntries(Object.entries(prefs.collectionGroupViews||{}).filter(([id,mode])=>db.binders.some(b=>b.id===id)&&collectionViewModes.has(mode))),groupItemViews:Object.fromEntries(Object.entries(prefs.groupItemViews||{}).filter(([id,mode])=>db.groups.some(g=>g.id===id)&&itemViewModes.has(mode)))}};const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`archive-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Backup exported')}catch(e){notify('Export failed: '+e.message)}}
function validateViewPreferences(x){
 if(x.viewPreferences===undefined)return;
 if(!x.viewPreferences||typeof x.viewPreferences!=='object'||Array.isArray(x.viewPreferences))throw Error('Invalid view preferences');
 for(const [key,allowed,records] of [['collectionGroupViews',collectionViewModes,x.binders],['groupItemViews',itemViewModes,x.groups||[]]]){
  const map=x.viewPreferences?.[key];if(map===undefined)continue;
  if(!map||typeof map!=='object'||Array.isArray(map))throw Error('Invalid catalogue view map');
  const ids=new Set(records.map(r=>r.id));
  if(Object.entries(map).some(([id,mode])=>!ids.has(id)||!allowed.has(mode)))throw Error('Invalid catalogue view preference');
 }
}
function validateBackup(x){if(!x||!['archive','card-archive'].includes(x.format)||x.version!==1||!Array.isArray(x.binders)||!Array.isArray(x.cards)||!Array.isArray(x.tags)||!x.images||typeof x.images!=='object')throw Error('Not a compatible Archive backup');const ids=new Set(x.binders.map(b=>b.id));if(x.groups!==undefined&&(!Array.isArray(x.groups)||x.groups.some(g=>!g.id||!ids.has(g.binderId)||typeof g.name!=='string')||new Set(x.groups.map(g=>g.id)).size!==x.groups.length))throw Error('Invalid groups');if(Array.isArray(x.groups)&&x.cards.some(c=>c.groupId&&!x.groups.some(g=>g.id===c.groupId&&g.binderId===c.binderId)))throw Error('Invalid group assignment');if(x.cards.some(c=>!validItemDetails(c.details)||c.copies!==undefined&&(!Array.isArray(c.copies)||c.copies.some(p=>!p||typeof p!=='object'||!validItemDetails(p.details)||p.imageId&&!x.images[p.imageId]))))throw Error('Invalid duplicate copy or missing image');if(x.binders.some(b=>!b.id||typeof b.name!=='string')||x.tags.some(t=>!t.id||typeof t.name!=='string')||x.cards.some(c=>!c.id||!ids.has(c.binderId)||typeof c.name!=='string'||!Array.isArray(c.tags)))throw Error('Backup contains invalid records');if(new Set(x.binders.map(b=>b.id)).size!==x.binders.length||new Set(x.cards.map(c=>c.id)).size!==x.cards.length||new Set(x.tags.map(t=>t.id)).size!==x.tags.length)throw Error('Duplicate record IDs');const tids=new Set(x.tags.map(t=>t.id));if(x.cards.some(c=>c.tags.some(t=>!tids.has(t))||c.imageId&&!x.images[c.imageId]))throw Error('Missing tag or image reference');for(const image of Object.values(x.images)){if(typeof image!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(image))throw Error('Invalid image payload')}validateViewPreferences(x)}
async function importBackup(file){let data;try{data=JSON.parse(await file.text());validateBackup(data)}catch(e){return notify('Invalid backup: '+e.message)}const existing=db.cards.length,coming=data.cards.length;modal('Restore backup',`<p>Backup verified: ${countLabel(data.binders.length,"shelf","shelves")}, ${countLabel(data.tags.length,"tag")}, ${Object.keys(data.images).length} images. Current archive: <b>${existing}</b> items. Backup: <b>${coming}</b> items, ${countLabel(data.binders.length,"shelf","shelves")}, ${countLabel(data.tags.length,"tag")}.</p><label class="field"><input type="radio" name="restore" value="add" checked style="width:auto"> Add all — keep existing items, including duplicates</label><label class="field"><input type="radio" name="restore" value="replace" style="width:auto"> Replace all — remove current items and shelves</label><p class="help">Images are included. Back up your existing collection first.</p>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'→',title:'Continue',fn:()=>{const mode=document.querySelector('input[name=restore]:checked').value;confirmText('Confirm restore',mode==='add'?`Add ${countLabel(coming,"item")} to the existing ${existing}?`:`Replace all ${countLabel(existing,"existing item","existing items")} with ${countLabel(coming,"item")} from the backup?`,mode==='add'?'ADD':'REPLACE',()=>{performRestore(data,mode).catch(e=>notify('Restore failed: '+e.message))},mode==='replace')}}])}
async function performRestore(data,mode){const priorShelfCount=db.binders.length;const priorItemCount=totalCards(db.cards);const oldImageIds=mode==='replace'?allImageIds(db.cards):[];const next=mode==='replace'?initial():structuredClone(db),binderMap=new Map(),groupMap=new Map(),tagMap=new Map(),imageWrites=[];for(const b of data.binders){let found=mode==='add'?next.binders.find(x=>x.name.toLowerCase()===b.name.toLowerCase()):null;const id=found?.id||uid();binderMap.set(b.id,id);if(!found)next.binders.push({...b,id})}for(const b of data.binders){const oldGroups=Array.isArray(data.groups)?data.groups.filter(g=>g.binderId===b.id):[];if(!oldGroups.length)oldGroups.push({id:'legacy-'+b.id,binderId:b.id,name:'Unsorted'});for(const g of oldGroups){const parent=binderMap.get(b.id);let found=mode==='add'?next.groups.find(x=>x.binderId===parent&&x.name.toLowerCase()===g.name.toLowerCase()):null;const id=found?.id||uid();groupMap.set(g.id,id);if(!found)next.groups.push({...g,id,binderId:parent})}}for(const t of data.tags){let found=mode==='add'?next.tags.find(x=>x.name.toLowerCase()===t.name.toLowerCase()):null;const id=found?.id||uid();tagMap.set(t.id,id);if(!found)next.tags.push({...t,id})}for(const c of data.cards){const id=uid(),imageId=c.imageId?uid():null;const copies=(c.copies||[]).map(copy=>{const newImageId=copy.imageId?uid():null;if(newImageId)imageWrites.push([newImageId,dataToBlob(data.images[copy.imageId])]);return {...copy,id:uid(),imageId:newImageId}});next.cards.push({...c,id,binderId:binderMap.get(c.binderId),groupId:groupMap.get(c.groupId)||groupMap.get('legacy-'+c.binderId)||next.groups.find(g=>g.binderId===binderMap.get(c.binderId))?.id,tags:[...new Set(c.tags.map(t=>tagMap.get(t)))],imageId,copies});if(imageId)imageWrites.push([imageId,dataToBlob(data.images[c.imageId])])}const written=[];try{for(const [id,blob] of imageWrites){await putImage(id,blob);written.push(id)}save(next);
 const incoming=data.viewPreferences||{};
 if(mode==='replace'){prefs.collectionGroupViews={};prefs.groupItemViews={}}
 for(const [oldId,modeName] of Object.entries(incoming.collectionGroupViews||{})){
  const id=binderMap.get(oldId);if(id&&collectionViewModes.has(modeName)&&(!prefs.collectionGroupViews?.[id]||mode==='replace'))(prefs.collectionGroupViews??={})[id]=modeName;
 }
 for(const [oldId,modeName] of Object.entries(incoming.groupItemViews||{})){
  const id=groupMap.get(oldId);if(id&&itemViewModes.has(modeName)&&(!prefs.groupItemViews?.[id]||mode==='replace'))(prefs.groupItemViews??={})[id]=normalizedItemView(modeName);
 }
 savePrefs();view={binder:null,group:null,card:null,search:false};words=[];filters=[];draft='';editMode=false;selected.clear();closeModal();render();const restoredItems=mode==='replace'?totalCards(next.cards):totalCards(next.cards)-priorItemCount;const restoredShelves=mode==='replace'?next.binders.length:next.binders.length-priorShelfCount;notify(`Restored ${countLabel(restoredItems,"item")} across ${countLabel(restoredShelves,"shelf","shelves")}`);if(mode==='replace'){const retained=new Set(allImageIds(next.cards));for(const oldId of oldImageIds)if(!retained.has(oldId))await deleteImage(oldId).catch(()=>{})}}catch(e){for(const id of written)await deleteImage(id).catch(()=>{});throw e}}
render();

// Warn before navigating away from a dirty item/copy editor with browser Back.
window.addEventListener('popstate',()=>{if($('modalRoot').querySelector('.modal[data-editor]'))safeCloseEditor()});

// v0.2.7 — Match DA connection status: browser online/offline events.
const offlineInfo = document.getElementById('offlineInfo');
function updateConnectionLabel(){
  if(offlineInfo) offlineInfo.textContent = navigator.onLine ? 'NETWORK: ONLINE · CATALOGUE: ON THIS DEVICE' : 'NETWORK: OFFLINE · CATALOGUE: ON THIS DEVICE';
}
window.addEventListener('online', updateConnectionLabel);
window.addEventListener('offline', updateConnectionLabel);
updateConnectionLabel();

// Autocomplete is derived from saved records, including physical copies; no new storage schema.
function attachMetadataSuggestions(){
  const fields=[['cCondition','condition'],['cLanguage','language'],['cPack','pack'],['copyCondition','condition'],['copyLanguage','language'],['copyPack','pack']];
  for(const [id,key] of fields){const input=$(id);if(!input)continue;
    const values=new Map();const activeType=collectibleTypeForBinder(view.binder);for(const c of db.cards.filter(c=>collectibleTypeForItem(c)===activeType))for(const record of [c,...(c.copies||[])]){const v=String(record[key]||'').trim();if(v&&!values.has(v.toLocaleLowerCase()))values.set(v.toLocaleLowerCase(),v)}
    const list=document.createElement('datalist');list.id=id+'Suggestions';for(const value of [...values.values()].sort((a,b)=>a.localeCompare(b))){const o=document.createElement('option');o.value=value;list.append(o)}
    input.after(list);input.setAttribute('list',list.id);
  }
}
